CREATE COLUMN TABLE "TEST_AP"."APZ_D_OELN" ("ID" INTEGER CS_INT GENERATED BY DEFAULT AS IDENTITY (start with 1 increment by 1), "EventCode" NVARCHAR(50), "Message" NVARCHAR(254), "Image" NVARCHAR(250), "Data" NVARCHAR(254), "Data1" NVARCHAR(254), "Data2" DATE CS_DAYDATE, "Data3" DATE CS_DAYDATE, "Data4" DOUBLE CS_DOUBLE, "DataExtra" NVARCHAR(5000), "SendUser" VARCHAR(254), "SendAll" CHAR(1) CS_FIXEDSTRING DEFAULT 'N', "Pending" CHAR(1) CS_FIXEDSTRING DEFAULT 'Y', "Success" CHAR(1) CS_FIXEDSTRING DEFAULT 'N', "Retry" INTEGER CS_INT DEFAULT 1, "Method" NVARCHAR(50) DEFAULT 'app', "CreateDate" DATE CS_DAYDATE DEFAULT CURRENT_DATE, "UpdateDate" DATE CS_DAYDATE DEFAULT CURRENT_DATE, "DatabaseName" NVARCHAR(50), "Title" NVARCHAR(100), PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE 